var Viewer=function(){var t={table:baseURL+"api/v2/analisis/getViewer"};return{start:function(){var e=this;$(".btn-back").click(function(t){parent.location=baseURL}),$.ajax({dataType:"json",type:"POST",url:t.table,global:!1,success:function(t){if(t.success)for($("#result").find("tbody").empty(),i=0;i<t.rows.length;i++){var a=$("<tr>"),n=t.rows[i];a.append($("<td>",{text:n.no,align:"center"})),a.append($("<td>",{text:n.nopes,align:"center"})),a.append($("<td>",{text:n.nama})),a.append($("<td>",{text:n.sex})),a.append($("<td>",{text:n.status_nama})),a.append($("<td>",{text:n.nama_tes})),a.append($("<td>",{text:n.nilai,align:"right"})),$("#result").find("tbody").append(a)}setTimeout(function(){e.start()},5e3)}})},show:function(){this.start()}}}();Viewer.show();